    def receive_message(self, message: Info) -> Info:  
        grid = message.message[0].data[1]               
        prev_move = message.message[0].data[0]  
        move = None  

        # --- Helper functions ---
        def get_N(grid):
            return len(grid)

        def get_box_size(N):
            sqrt = int(math.isqrt(N))
            if sqrt * sqrt == N:
                return sqrt
            # Otherwise, for non-square cases. But classic Sudoku is sqrt-sqrt boxes.
            # For now, assume only normal grids encountered.
            return None

        def valid_move(grid, r, c, val):
            N = len(grid)
            box = get_box_size(N)
            # Check row, col, box
            for i in range(N):
                if grid[r][i] == val: return False
                if grid[i][c] == val: return False
            br = (r//box)*box
            bc = (c//box)*box
            for i in range(box):
                for j in range(box):
                    if grid[br+i][bc+j]==val:
                        return False
            return True

        def find_valid_moves(grid, allowed_cells=None):
            N = len(grid)
            moves = []
            for r in range(N):
                for c in range(N):
                    if grid[r][c]!=0: continue
                    if allowed_cells is not None:
                        if (r,c) not in allowed_cells: continue
                    # Try placing each possible value
