                        if valid_move(grid,r,c,val):
                            moves.append( ((r,c),val) )
            return moves

        def get_allowed_cells(grid, prev_move):
            N = len(grid)
            if prev_move is None:
                return None # all cells allowed
            (pr,pc),_ = prev_move
            # cells in row pr or col pc that are empty
            allowed = set()
            for i in range(N):
                if grid[pr][i]==0:
                    allowed.add((pr,i))
                if grid[i][pc]==0:
                    allowed.add((i,pc))
            # if none, allowed is all empty
