    # --- Helper functions start here ---

    def board_n(self, grid):
        return len(grid)

    def get_block_size(self, N):
        sqrtN = int(math.isqrt(N))
        if sqrtN * sqrtN != N:
            # fallback, for non-standard sizes
            sqrtN = int(N ** 0.5)
        return sqrtN

    def get_block_cells(self, row, col, N):
        M = self.get_block_size(N)
        block_r = (row // M)
        block_c = (col // M)
        res = []
        for dr in range(M):
            for dc in range(M):
                r = block_r * M + dr
                c = block_c * M + dc
                res.append((r, c))
        return res

    def sudoku_violates(self, grid, row, col, val):
        N = len(grid)
        M = self.get_block_size(N)
        # Check row/col
        if any(grid[row][i] == val for i in range(N)):
            return True
        if any(grid[i][col] == val for i in range(N)):
            return True
        # Check subgrid
        block_r = (row // M) * M
        block_c = (col // M) * M
        for r in range(block_r, block_r+M):
            for c in range(block_c, block_c+M):
                if grid[r][c] == val:
                    return True
        return False

    def get_possible_numbers(self, grid, row, col):
        N = len(grid)
        blacklist = set()
        # Row
        for k in range(N):
            if grid[row][k]!=0:
                blacklist.add(grid[row][k])
        # Col
        for k in range(N):
            if grid[k][col]!=0:
                blacklist.add(grid[k][col])
        # Subgrid
        M = self.get_block_size(N)
        block_r = (row // M) * M
        block_c = (col // M) * M
        for r in range(block_r, block_r+M):
            for c in range(block_c, block_c+M):
                if grid[r][c]!=0:
                    blacklist.add(grid[r][c])
        return [v for v in range(1,N+1) if v not in blacklist]

    def all_valid_moves(self, grid, prev_move):
        N = len(grid)
        if prev_move is None:
            coords = [(r,c) for r in range(N) for c in range(N) if grid[r][c]==0]
        else:
            last_r, last_c = prev_move[0]
            candidates = set()
            for i in range(N):
                if grid[last_r][i] == 0:
                    candidates.add( (last_r, i) )
                if grid[i][last_c] == 0:
                    candidates.add( (i, last_c) )
            coords = list(candidates)
            # If no moves in rc, fall back to anywhere rule
            if not coords:
                coords = [(r,c) for r in range(N) for c in range(N) if grid[r][c]==0]
        moves = []
        for (r,c) in coords:
            for val in self.get_possible_numbers(grid, r, c):
                moves.append( ((r,c), val) )
        return moves

