        moves = self.all_valid_moves(grid, prev_move)
        # 1. Check for any instant win
        for m in moves:
            if self.is_winning_move(grid, m):
                return m
        # 2. Otherwise, minimize opponent's options (defensive play)
        min_opp, best = float('inf'), None
        for m in moves:
            cnt, _ = self.opp_possible_moves_count(grid, m)
            if cnt < min_opp:
                min_opp, best = cnt, m
        return best if best is not None else moves[0]

