    size = int(math.sqrt(n))
    result = []
    for r in range(br * size, (br + 1) * size):
        for c in range(bc * size, (bc + 1) * size):
            result.append((r, c))
    return result

def sudoku_valid_moves(grid: List[List[int]], n: int) -> List[List[Set[int]]]:
    """Return a 2D list of sets: for each empty cell, a set of legal numbers."""
    size = int(math.sqrt(n))
    # Precompute used numbers
    row_used = [set() for _ in range(n)]
    col_used = [set() for _ in range(n)]
    block_used = [[set() for _ in range(size)] for _ in range(size)]
    for r in range(n):
        for c in range(n):
            val = grid[r][c]
            if val != 0:
                row_used[r].add(val)
                col_used[c].add(val)
                br, bc = r // size, c // size
                block_used[br][bc].add(val)
    legal = [[set() for _ in range(n)] for _ in range(n)]
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                br, bc = r // size, c // size
                legal[r][c] = set(range(1, n+1)) - row_used[r] - col_used[c] - block_used[br][bc]
    return legal

def all_empty_in_rc(grid: List[List[int]], row: int, col: int) -> Set[Tuple[int, int]]:
    n = len(grid)
    result = set()
    for i in range(n):
        if grid[row][i] == 0:
            result.add((row,i))
        if grid[i][col] == 0:
            result.add((i,col))
    return result

def all_empty_cells(grid: List[List[int]]) -> Set[Tuple[int,int]]:
