    def get_valid_cells(self, grid: List[List[int]], prev_move: Optional[List]) -> List[Tuple[int,int]]:
        N = len(grid)
        if prev_move is None:
            # First move: Any empty cell
            return [(r,c) for r in range(N) for c in range(N) if grid[r][c]==0]
        row, col = prev_move[0]
        candidates = set()
        # Add empty cells in row
        for c in range(N):
            if grid[row][c]==0:
                candidates.add((row,c))
        # Add empty cells in column
        for r in range(N):
            if grid[r][col]==0:
                candidates.add((r,col))
        # If no candidates, can move anywhere
        if not candidates:
            return [(r,c) for r in range(N) for c in range(N) if grid[r][c]==0]
        return list(candidates)

    def get_block_indices(self, N: int) -> List[Tuple[int,int]]:
        # Returns list of block top-left corners
        block_size = int(math.isqrt(N))
        return [(i,j) for i in range(0,N,block_size) for j in range(0,N,block_size)]

    def block_of(self, r: int, c: int, N: int) -> Tuple[int, int]:
        bsize = int(math.isqrt(N))
        return (r//bsize, c//bsize)

    def possible_candidates(self, grid: List[List[int]], row: int, col: int) -> Set[int]:
        N = len(grid)
        used = set()
        used.update(grid[row])
        used.update(grid[r][col] for r in range(N))
        # Block
        bsize = int(math.isqrt(N))
        r0, c0 = (row//bsize)*bsize, (col//bsize)*bsize
        for dr in range(bsize):
            for dc in range(bsize):
                used.add(grid[r0+dr][c0+dc])
        return set(range(1,N+1)) - used

    def sudoku_is_valid(self, grid: List[List[int]], row:int, col:int, val:int) -> bool:
        N = len(grid)
        # Row
        for c in range(N):
            if grid[row][c] == val:
                return False
        # Col
        for r in range(N):
            if grid[r][col] == val:
                return False
        # Block
        bsize = int(math.isqrt(N))
        r0, c0 = (row//bsize)*bsize, (col//bsize)*bsize
        for dr in range(bsize):
            for dc in range(bsize):
                if grid[r0+dr][c0+dc] == val:
                    return False
        return True

