        # Given we move (r, c) with number val, enumerate opponent's possible cells
        next_prev_move = [(move[0],move[1]), move[2]]
        return self.get_valid_cells(grid, next_prev_move)

    def win_if_forced(self, grid: List[List[int]], prev_move: Optional[List], cell: Tuple[int,int], value: int) -> bool:
        # Returns True if after playing value at cell, opponent will have NO valid move available
        N = len(grid)
        temp_grid = [row[:] for row in grid]
        temp_grid[cell[0]][cell[1]] = value
        next_prev_move = [cell, value]
        opp_cells = self.get_valid_cells(temp_grid, next_prev_move)
        for (r,c) in opp_cells:
            cand = self.possible_candidates(temp_grid, r, c)
            if cand:
                return False
        return True

