        # Returns total number of (cell,value) pairs for opponent
        N = len(grid)
        opp_cells = self.get_valid_cells(grid, next_prev_move)
        total = 0
        for (r,c) in opp_cells:
            cand = self.possible_candidates(grid, r, c)
            total += len(cand)
        return total

