        best_win = None
        best_trap = []
        best_trap_score = 1000000
        fallback = None
        fallback_score = 1000000
        # Try to find instantly winning move
        for (r,c) in my_cells:
            candidates = self.possible_candidates(grid,r,c)
            if not candidates:
