                # 2. Else: How many options does opponent have after this move?
                temp_grid = [row[:] for row in grid]
                temp_grid[r][c] = v
                next_prev_move = [(r,c), v]
                opp_option_count = self.count_opponent_options(temp_grid, next_prev_move)
                if opp_option_count < best_trap_score:
                    best_trap = [[(r,c), v]]
                    best_trap_score = opp_option_count
                elif opp_option_count == best_trap_score:
                    best_trap.append([(r,c), v])
                # Fallback: just in case, any move
                if fallback is None or opp_option_count < fallback_score:
                    fallback = [(r,c), v]
                    fallback_score = opp_option_count
            if best_win:
                break
        if best_win:
            move = best_win
        elif best_trap:
            move = best_trap[0]
        else:
            move = fallback
        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
            message=[BaseMessageDataType(data=move, type='custom')]  
        )

