from pydantic import BaseModel
from typing import List, Optional, Dict, Any, Tuple, Set
from enum import Enum
from abc import abstractmethod

from system.message import Info
from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy
import math
import random


def box_index(row: int, col: int, N: int, box_size: int) -> int:
    return (row // box_size) * box_size + (col // box_size)


def compute_constraint_sets(grid: List[List[int]]) -> Tuple[List[Set[int]], List[Set[int]], List[Set[int]]]:
    N = len(grid)
    box_size = int(math.isqrt(N))
    rows = [set() for _ in range(N)]
    cols = [set() for _ in range(N)]
    boxes = [set() for _ in range(N)]
    for r in range(N):
        for c in range(N):
            v = grid[r][c]
            if v != 0:
                rows[r].add(v)
                cols[c].add(v)
                bx = box_index(r, c, N, box_size)
                boxes[bx].add(v)
    return rows, cols, boxes


def get_allowed_values(r:int, c:int, rows, cols, boxes, N, box_size) -> Set[int]:
    bx = box_index(r, c, N, box_size)
    return set(range(1, N+1)) - rows[r] - cols[c] - boxes[bx]


def all_empty_cells(grid):
    for r in range(len(grid)):
        for c in range(len(grid)):
            if grid[r][c] == 0:
                yield (r, c)

def compute_playable_cells(prev_move, grid):
    # Return list of cells (r, c) where a move may be made according to Sudokill rules
    if prev_move is None:
        return list(all_empty_cells(grid))
    prev_rc = prev_move[0]
    r0, c0 = prev_rc
    N = len(grid)
    playable = set()
    # same row
    for cc in range(N):
        if grid[r0][cc] == 0:
            playable.add((r0, cc))
    # same col
    for rr in range(N):
        if grid[rr][c0] == 0:
            playable.add((rr, c0))
    if not playable:
        # corner case, all blocked, Sudokill: can move anywhere
        return list(all_empty_cells(grid))
    return list(playable)


def is_win_for_us(grid, move, N, box_size):
    # Returns True iff after making move, opponent has zero legal moves
    # move = [(r, c), v]
    # grid is a copy, not mutated in place
    # Assumes move is legal for us
    next_grid = [row[:] for row in grid]
    (r, c), v = move
    next_grid[r][c] = v
    # build constraint sets
    rows, cols, boxes = compute_constraint_sets(next_grid)
    next_moves = compute_playable_cells([(r, c), v], next_grid)
    found_legal = False
    for (nr, nc) in next_moves:
        allowed = get_allowed_values(nr, nc, rows, cols, boxes, N, box_size)
        if allowed:
            found_legal = True
            break
    return not found_legal


def num_opponent_responses(grid, move, N, box_size):
    # After this move, how many legal responses does opponent have? Used for minimax tiebreaker.
    next_grid = [row[:] for row in grid]
    (r, c), v = move
    next_grid[r][c] = v
    # build constraint sets
    rows, cols, boxes = compute_constraint_sets(next_grid)
    next_moves = compute_playable_cells([(r, c), v], next_grid)
    total = 0
    for (nr, nc) in next_moves:
        allowed = get_allowed_values(nr, nc, rows, cols, boxes, N, box_size)
        total += len(allowed)
    return total


def find_immediate_win_moves(grid, playable_cells, N, box_size, constraint_sets):
    # Return all moves ([(r, c), v]) which, if played, leave opponent with no legal moves -- i.e., win immediately
    winning_moves = []
    # This is expensive only if many open cells remain; in late/endgame it's fast
    rows, cols, boxes = constraint_sets
    for (r, c) in playable_cells:
        allowed = get_allowed_values(r, c, rows, cols, boxes, N, box_size)
        for v in allowed:
            move = [(r, c), v]
            if is_win_for_us(grid, move, N, box_size):
                winning_moves.append(move)
    return winning_moves


def find_best_minimax_move(grid, playable_cells, N, box_size, constraint_sets):
    # For each legal move, count how many responses opponent would have; pick the one(s) with fewest responses
    rows, cols, boxes = constraint_sets
    best_moves = []
    best_response_cnt = float('inf')
    for (r, c) in playable_cells:
        allowed = get_allowed_values(r, c, rows, cols, boxes, N, box_size)
        for v in allowed:
            move = [(r, c), v]
            try:
                resp_cnt = num_opponent_responses(grid, move, N, box_size)
            except Exception as e:
                continue  # Should not happen
            if resp_cnt < best_response_cnt:
                best_moves = [move]
                best_response_cnt = resp_cnt
            elif resp_cnt == best_response_cnt:
                best_moves.append(move)
    return best_moves, best_response_cnt


def pick_any_legal_move(grid, playable_cells, N, box_size, constraint_sets):
    # If no fancy attack/defense, pick any legal move
    rows, cols, boxes = constraint_sets
    for (r, c) in playable_cells:
        allowed = get_allowed_values(r, c, rows, cols, boxes, N, box_size)
        if allowed:
            return [(r, c), random.choice(list(allowed))]
    # Emergency fallback
    raise Exception('No legal moves found, should not happen!')


