    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom
    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)
    def receive_message(self, message: Info) -> Info:
        grid = message.message[0].data[1]
        prev_move = message.message[0].data[0]
        move = None
        N = len(grid)
        box_size = int(math.isqrt(N))
        constraint_sets = compute_constraint_sets(grid)
        playable_cells = compute_playable_cells(prev_move, grid)
        # 1. Look for immediate win (opponent loses)
        winning_moves = find_immediate_win_moves(grid, playable_cells, N, box_size, constraint_sets)
        if winning_moves:
            move = random.choice(winning_moves)
        else:
            # 2. Minimax: choose move that minimizes number of opponent's responses
            moves, best_resp = find_best_minimax_move(grid, playable_cells, N, box_size, constraint_sets)
            move = random.choice(moves)
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=move, type='custom')]
        )

