    for cc in range(N):
        if grid[r0][cc] == 0:
            playable.add((r0, cc))
    # same col
    for rr in range(N):
        if grid[rr][c0] == 0:
            playable.add((rr, c0))
    if not playable:
        # corner case, all blocked, Sudokill: can move anywhere
        return list(all_empty_cells(grid))
    return list(playable)


