    # Returns True iff after making move, opponent has zero legal moves
    # move = [(r, c), v]
    # grid is a copy, not mutated in place
    # Assumes move is legal for us
    next_grid = [row[:] for row in grid]
    (r, c), v = move
    next_grid[r][c] = v
    # build constraint sets
    rows, cols, boxes = compute_constraint_sets(next_grid)
    next_moves = compute_playable_cells([(r, c), v], next_grid)
    found_legal = False
    for (nr, nc) in next_moves:
        allowed = get_allowed_values(nr, nc, rows, cols, boxes, N, box_size)
        if allowed:
            found_legal = True
            break
    return not found_legal


