    next_grid[r][c] = v
    # build constraint sets
    rows, cols, boxes = compute_constraint_sets(next_grid)
    next_moves = compute_playable_cells([(r, c), v], next_grid)
    total = 0
    for (nr, nc) in next_moves:
        allowed = get_allowed_values(nr, nc, rows, cols, boxes, N, box_size)
        total += len(allowed)
    return total


