    # Return all moves ([(r, c), v]) which, if played, leave opponent with no legal moves -- i.e., win immediately
    winning_moves = []
    # This is expensive only if many open cells remain; in late/endgame it's fast
    rows, cols, boxes = constraint_sets
    for (r, c) in playable_cells:
        allowed = get_allowed_values(r, c, rows, cols, boxes, N, box_size)
        for v in allowed:
            move = [(r, c), v]
            if is_win_for_us(grid, move, N, box_size):
