        self.name = self._model.name  
        self.history = self._model.history  
        self.strategy_type = StrategyType.Custom  

    def update_model_field(self, field_name: str, value: Any):  
        if hasattr(self._model, field_name):  
            setattr(self._model, field_name, value)  

    def receive_message(self, message: Info) -> Info:  
        # grid is list of list, with each list is int     
        grid = message.message[0].data[1]           
        # prev_move is [(row_index, col_index), value], if you are the first move, it is None
        prev_move = message.message[0].data[0]  
        # return the decision with the format [(row_index, col_index), value]  
        move = None  

        ###############################
        # Helper functions
        ###############################
        def get_N_and_boxsize(grid):
            N = len(grid)
            boxsize = int(math.isqrt(N))
            return N, boxsize

        def get_empty_cells(grid):
            cells = []
            N = len(grid)
            for r in range(N):
                for c in range(N):
                    if grid[r][c]==0:
                        cells.append((r,c))
            return cells

        def possible_numbers_for_cell(grid, r, c):
            N, boxsize = get_N_and_boxsize(grid)
            used = set()
            # row
            used.update(grid[r][i] for i in range(N) if grid[r][i]!=0)
            # col
            used.update(grid[i][c] for i in range(N) if grid[i][c]!=0)
            # box
            br = (r//boxsize)*boxsize
            bc = (c//boxsize)*boxsize
            for i in range(br, br+boxsize):
                for j in range(bc, bc+boxsize):
                    if grid[i][j]!=0:
                        used.add(grid[i][j])
            return [n for n in range(1,N+1) if n not in used]

        def is_valid_move(grid, r, c, v):
            N, boxsize = get_N_and_boxsize(grid)
            # row
            if v in grid[r]:
                return False
            # col
            if v in [grid[i][c] for i in range(N)]:
                return False
            # box
            br = (r//boxsize)*boxsize
            bc = (c//boxsize)*boxsize
            for i in range(br, br+boxsize):
                for j in range(bc, bc+boxsize):
                    if grid[i][j]==v:
                        return False
            return True

        def get_allowed_moves(grid, prev_move):
            N = len(grid)
            empty_cells = get_empty_cells(grid)
            if prev_move is None:
                return empty_cells
            else:
                prev_r, prev_c = prev_move[0]
                in_row = [(prev_r,c) for c in range(N) if grid[prev_r][c]==0]
                in_col = [(r,prev_c) for r in range(N) if grid[r][prev_c]==0]
                allowed = set(in_row+in_col)
                if allowed:
                    return list(allowed)
                else:
                    return empty_cells

        def count_opponent_responses(new_grid, move_pos):
            '''Count the number of legal opponent move options after making a move at move_pos'''
            opp_moves = get_allowed_moves(new_grid, [move_pos, new_grid[move_pos[0]][move_pos[1]]])
            count = 0
            for (r,c) in opp_moves:
                for v in possible_numbers_for_cell(new_grid, r, c):
                    if is_valid_move(new_grid, r, c, v):
                        count += 1
                        # Short circuit: if count > 1, don't need to compute further for now
                        if count > 0:
                            return count
            return count # 0 means opponent can't move (forced win)

        #######################
        # Main logic
        #######################

        N, boxsize = get_N_and_boxsize(grid)
        allowed_cells = get_allowed_moves(grid, prev_move)

        # For each allowed cell, try each possible number. Collect all legal moves, categorize by how many opponent replies they enable
        best_moves = []
        minimal_replies = float('inf')
        for (r,c) in allowed_cells:
            for v in possible_numbers_for_cell(grid, r, c):
                if not is_valid_move(grid, r, c, v):
                    continue
                # simulate
                grid2 = [row[:] for row in grid]
                grid2[r][c] = v
                replies = 0
                # How many moves does opponent have in this resulting position?
                opp_reply_count = 0
                # check if opponent immediately loses:
                opp_cells = get_allowed_moves(grid2, [(r,c), v])
                lost = True
                for (rr,cc) in opp_cells:
                    poss2 = possible_numbers_for_cell(grid2, rr, cc)
                    if any(is_valid_move(grid2, rr, cc, vv) for vv in poss2):
                        lost = False
                        break
                if lost:
                    # This is a forced win move
                    move = [(r,c), v]
                    return Info(  
                        sender=self.__class__.__name__,  
                        receiver=message.sender,  
                        difficulty=message.difficulty,  
                        message=[BaseMessageDataType(data=move, type='custom')]  
                    )
                # If not forced win, count number of safe responses opponent can make
                opp_reply_count = 0
                for (rr,cc) in opp_cells:
                    for vv in possible_numbers_for_cell(grid2, rr, cc):
                        if is_valid_move(grid2, rr, cc, vv):
                            opp_reply_count += 1
                if opp_reply_count < minimal_replies:
                    minimal_replies = opp_reply_count
                    best_moves = [[(r,c), v]]
                elif opp_reply_count == minimal_replies:
                    best_moves.append([(r,c), v])

        # If no forced win is found, play move with minimal opponent replies
        if best_moves:
            move = best_moves[0] # Arbitrary if multiple
        else:
            # Fallback: just play any valid move
            for (r,c) in allowed_cells:
                for v in possible_numbers_for_cell(grid, r, c):
                    if is_valid_move(grid, r, c, v):
                        move = [(r,c), v]
                        break
                if move is not None:
                    break

        return Info(  
            sender=self.__class__.__name__,  
            receiver=message.sender,  
            difficulty=message.difficulty,  
