def get_box_range(n, row, col):
    box_n = int(math.isqrt(n))
    box_row = (row // box_n) * box_n
    box_col = (col // box_n) * box_n
    return box_row, box_col, box_n

def get_candidates(grid: List[List[int]], row: int, col: int) -> Set[int]:
    n = len(grid)
    if grid[row][col] != 0:
        return set()
    full = set(range(1, n+1))
    row_vals = set(grid[row][j] for j in range(n) if grid[row][j] != 0)
    col_vals = set(grid[i][col] for i in range(n) if grid[i][col] != 0)
    box_row, box_col, box_n = get_box_range(n, row, col)
    box_vals = set()
    for i in range(box_row, box_row+box_n):
        for j in range(box_col, box_col+box_n):
            if grid[i][j]!=0:
                box_vals.add(grid[i][j])
    return full - row_vals - col_vals - box_vals

def is_valid_move(grid: List[List[int]], row: int, col: int, val: int) -> bool:
    n = len(grid)
    # row
    if any(grid[row][j] == val for j in range(n)):
        return False
    # col
    if any(grid[i][col] == val for i in range(n)):
        return False
    # box
    box_row, box_col, box_n = get_box_range(n, row, col)
    for i in range(box_row, box_row+box_n):
        for j in range(box_col, box_col+box_n):
            if grid[i][j] == val:
                return False
    return True

