        col_cells = [(i, c) for i in range(n) if grid[i][c]==0]
        cells = list(set(row_cells + col_cells))
        if len(cells)==0:
            # Nowhere in row/col, allowed to go anywhere
            return get_available_cells(grid, None)
        return cells

def count_next_legal_moves(grid: List[List[int]], prev_move: List) -> int:
    # Return number of possible valid moves (cell,val) opp can play after this simulated move
    n = len(grid)
    cells = get_available_cells(grid, prev_move)
    cnt = 0
    for (i, j) in cells:
