# Helper functions for Sudoku logic

def get_box_indices(N: int, box_row: int, box_col: int, box_size: int) -> List[Tuple[int, int]]:
    indices = []
    for i in range(box_row * box_size, (box_row + 1) * box_size):
        for j in range(box_col * box_size, (box_col + 1) * box_size):
            indices.append((i, j))
    return indices


def get_candidates(grid: List[List[int]], N: int, row: int, col: int, box_size: int) -> Set[int]:
    if grid[row][col] != 0:
        return set()
    used = set()
    # Row and col
    for k in range(N):
        used.add(grid[row][k])
        used.add(grid[k][col])
    # Box
    box_row = row // box_size
    box_col = col // box_size
    for (i, j) in get_box_indices(N, box_row, box_col, box_size):
        used.add(grid[i][j])
    return set(range(1, N + 1)) - used


def get_all_empty_cells(grid: List[List[int]], N: int) -> List[Tuple[int, int]]:
    return [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 0]


def get_empty_cells_in_row_or_col(grid: List[List[int]], N: int, row: int, col: int) -> List[Tuple[int, int]]:
    cells = set()
    for k in range(N):
        if grid[row][k] == 0:
            cells.add((row, k))
        if grid[k][col] == 0:
            cells.add((k, col))
    return list(cells)


def is_legal_move(grid: List[List[int]], N: int, row: int, col: int, value: int, box_size: int) -> bool:
    # check row
    for j in range(N):
        if grid[row][j] == value:
            return False
    # check col
    for i in range(N):
        if grid[i][col] == value:
            return False
    # check box
    box_row = row // box_size
    box_col = col // box_size
    for (i, j) in get_box_indices(N, box_row, box_col, box_size):
        if grid[i][j] == value:
