        grid = message.message[0].data[1]             
        prev_move = message.message[0].data[0]  
        N = len(grid)
        sqrtN = int(math.isqrt(N))

        def get_empty_cells(grid):
            return [(r, c) for r in range(N) for c in range(N) if grid[r][c] == 0]

        def get_cells_in_row_col(prev_move, grid):
            if prev_move is None:
                return get_empty_cells(grid)
            row, col = prev_move[0]
            allowed = set()
            for c in range(N):
                if grid[row][c] == 0:
                    allowed.add((row, c))
            for r in range(N):
                if grid[r][col] == 0:
                    allowed.add((r, col))
            return list(allowed)

        def get_block_start(x):
            return (x // sqrtN) * sqrtN

        def possible_values(grid, r, c):
            used = set()
            used.update(grid[r])
            used.update(grid[rr][c] for rr in range(N))
            br, bc = get_block_start(r), get_block_start(c)
            for rr in range(br, br+sqrtN):
                for cc in range(bc, bc+sqrtN):
                    used.add(grid[rr][cc])
            return [v for v in range(1, N+1) if v not in used]

        def valid_move(grid, r, c, v):
            if grid[r][c] != 0:
                return False
            if v in grid[r]:
                return False
            if v in (grid[rr][c] for rr in range(N)):
                return False
            br, bc = get_block_start(r), get_block_start(c)
            for rr in range(br, br+sqrtN):
                for cc in range(bc, bc+sqrtN):
                    if grid[rr][cc] == v:
