                    receiver=message.sender,
                    difficulty=message.difficulty,
                    message=[BaseMessageDataType(data=move, type='custom')]
                )
        # Step 2: For each move, see if it is winning (opponent cannot reply)
        winning_moves = []
        forced_loser_moves = []
        min_opp_count = N*N+1
        best_moves = []
        for move in candidate_moves:
            # Simulate playing move
            new_grid = copy.deepcopy(grid)
            r, c = move[0]
            v = move[1]
            new_grid[r][c] = v
            # Check if valid (should always be true by earlier check)
            # Now, what options does opponent have?
            opp_cells = opponent_cells([(r, c), v], new_grid)
            opp_moves = []
            for (rr, cc) in opp_cells:
