            # Check if all opponent moves are illegal (edge case)
            # Or, for each opponent move, simulate their move: are we setting up a forced loss?
            # (optional lookahead: can we force opponent into a state where any reply loses?)
            # For efficiency, we'll record moves that minimumly restrict opponent
            if len(opp_moves) < min_opp_count:
                min_opp_count = len(opp_moves)
                best_moves = [move]
            elif len(opp_moves) == min_opp_count:
                best_moves.append(move)
        # Step 3: Pick the best move
